  summary = 'This syllabus preserves the economics spine and expands it into a course that can serve advanced undergraduates, master''s students, or mathematically mature policy/business students. The additions emphasize proof-level equilibrium reasoning, information economics, mechanism design, modern market design, computational and network settings, behavioral evidence, and a capstone analysis.',
  data = $gthjson${"slug": "game-theory", "title": "Game Theory", "description": "This syllabus preserves the economics spine and expands it into a course that can serve advanced undergraduates, master's students, or mathematically mature policy/business students. The additions emphasize proof-level equilibrium reasoning, information economics, mechanism design, modern market design, computational and network settings, behavioral evidence, and a capstone analysis.", "topics": [{"id": "098ec08f-4078-44ed-b620-33286cadbe4e", "type": "topic", "title": "Strategic Reasoning and Mathematical Foundations", "description": "Frame strategic situations as models: players, actions, preferences, information, timing, beliefs, and payoffs.", "children": [{"id": "528940df-6930-417f-b5ac-0d6c5eaef3de", "type": "subtopic", "title": "Players, actions, and outcomes", "children": [{"id": "b90e9d7a-490c-41bc-9820-5288dc42fa8d", "type": "concept", "title": "Players and decision makers"}, {"id": "bc98b151-da61-4f5c-a54b-ad494cd5fe97", "type": "concept", "title": "Action sets and strategy sets"}, {"id": "ceaf6c31-2e47-49de-93d4-fe8ba2527f8d", "type": "concept", "title": "Outcomes, consequences, and feasibility constraints"}], "description": "The point is to translate messy social or economic conflict into a clear model of who can do what and what may happen."}, {"id": "229e95b9-529a-442b-a4a6-620de67e2dec", "type": "subtopic", "title": "Preferences and payoffs", "children": [{"id": "63e890bf-49cd-4ac0-8dfc-82d2701f9099", "type": "concept", "title": "Ordinal versus cardinal utility"}, {"id": "2fdf0c86-d558-4489-9f5b-a23356534bf8", "type": "concept", "title": "Expected utility"}, {"id": "384c4861-0691-42d4-aa4c-92eeba5cb76d", "type": "concept", "title": "Risk preferences and payoff normalization"}], "description": "Students learn that payoffs represent ranked objectives, not necessarily money alone."}, {"id": "f04d7d92-249a-4229-bdcb-4d6d74cf4d12", "type": "subtopic", "title": "Information and timing", "children": [{"id": "b4193f96-b79b-47e9-bc4b-b0922b5373c8", "type": "concept", "title": "Complete versus incomplete information"}, {"id": "880be03d-4f5f-4195-bf97-6e7ca2018d74", "type": "concept", "title": "Perfect versus imperfect information"}, {"id": "ca58f1de-d6fd-45c4-b04f-341468d6452a", "type": "concept", "title": "Simultaneous and sequential timing"}], "description": "Game theory begins by asking who knows what, when they know it, and when they move."}]}, {"id": "6a8a9e6d-34f8-4a32-8744-30998d86400f", "type": "topic", "title": "Strategic-Form Games and Solution Concepts", "description": "Represent simultaneous-move games and compare what different assumptions about rationality imply.", "children": [{"id": "47299d89-0907-4f43-9f43-20469a6b4358", "type": "subtopic", "title": "Normal-form representation", "children": [{"id": "f76e1432-1a1b-4a8c-ac68-3c5537cc97d4", "type": "concept", "title": "Two-player matrices"}, {"id": "f07f778b-f868-4caa-99a2-8620272665d9", "type": "concept", "title": "n-player finite games"}, {"id": "79ff87df-6b94-4c29-a7b7-39a77e588610", "type": "concept", "title": "Best-response correspondences"}], "description": "Strategic-form games make interdependence visible in a compact payoff matrix or formal tuple."}, {"id": "aeda82ca-ac3c-4908-928f-089d50dbcfb5", "type": "subtopic", "title": "Classic benchmark games", "children": [{"id": "32f87d46-e95e-4c11-9c0f-fd1f6eadce5d", "type": "concept", "title": "Prisoner's dilemma"}, {"id": "0ce0cc89-7097-45c3-9aed-e09d8c2e0b1a", "type": "concept", "title": "Battle of the sexes"}, {"id": "61e80857-7020-41f2-88fe-fe72f0b3915d", "type": "concept", "title": "Matching pennies and coordination games"}], "description": "Canonical games build intuition for conflict, coordination, commitment, and social dilemmas."}, {"id": "bb882e6b-6dbd-42cc-b4f3-f916db43bc4f", "type": "subtopic", "title": "Solution-concept comparison", "children": [{"id": "893a9f49-f03b-4f0b-b1f4-892a3e5075d1", "type": "concept", "title": "Dominant-strategy equilibrium"}, {"id": "5f506aa0-c015-42f1-9367-5463714c4bf8", "type": "concept", "title": "Nash equilibrium"}, {"id": "ea378640-20b7-4c15-b01a-5bdfeb92dd59", "type": "concept", "title": "Correlated and coarse-correlated equilibrium preview"}], "description": "Different solution concepts answer different questions about rationality and prediction."}]}, {"id": "54fe95d1-878d-4af6-9b59-806bf2664ceb", "type": "topic", "title": "Dominance, Rationalizability, and Iterated Reasoning", "description": "Use elimination and belief-based reasoning to simplify games before jumping to equilibrium.", "children": [{"id": "c7a53fb8-2b20-43da-b6bf-a9408a4c5fe3", "type": "subtopic", "title": "Dominated strategies", "children": [{"id": "6ea6399f-ac24-4762-8692-f1f50c1e4379", "type": "concept", "title": "Strict dominance"}, {"id": "082c62ff-b51e-4716-83ef-b9d0821b266e", "type": "concept", "title": "Weak dominance"}, {"id": "4a687364-86bd-4216-9dc5-fffd6e73aa4c", "type": "concept", "title": "Dominance by mixed strategies"}], "description": "Dominance identifies choices that should not survive rational scrutiny."}, {"id": "12aee770-3b77-45ab-97fa-d5f81bc4fcbb", "type": "subtopic", "title": "Iterated elimination", "children": [{"id": "18989901-ce0d-4341-9a78-0f0742a63288", "type": "concept", "title": "Iterated deletion of strictly dominated strategies"}, {"id": "d69c2db5-7782-4799-a1bf-a726dbc641ef", "type": "concept", "title": "Order dependence with weak dominance"}, {"id": "47b84297-215a-4841-b3dc-e11024b793b2", "type": "concept", "title": "Surviving strategies and solution sets"}], "description": "Elimination procedures show how common knowledge of rationality narrows plausible play."}, {"id": "2372ced2-863b-4ef5-946f-9159e28c275f", "type": "subtopic", "title": "Rationalizability", "children": [{"id": "15c2d77a-17f1-47c0-8f4d-029e528a4871", "type": "concept", "title": "Best responses to beliefs"}, {"id": "d8e900ba-763f-443e-9e0b-c29442aa0f24", "type": "concept", "title": "Common knowledge of rationality"}, {"id": "ab54ff6d-8b66-4a0b-9397-07916fd8147f", "type": "concept", "title": "Relationship to Nash equilibrium"}], "description": "Rationalizability links choices to beliefs rather than requiring mutually correct equilibrium beliefs."}]}, {"id": "281b0310-4c5a-4b4c-bcb5-bab510ecf156", "type": "topic", "title": "Nash Equilibrium in Pure and Mixed Strategies", "description": "Find stable predictions where no player wants to deviate, including randomized strategies.", "children": [{"id": "4df9dc3c-d3c9-4af4-9ad1-afc0af7b3c07", "type": "subtopic", "title": "Pure-strategy Nash equilibrium", "children": [{"id": "0380e0a8-4d3b-4441-beb8-ea827e07135a", "type": "concept", "title": "Best-response marking"}, {"id": "77bfa314-9b73-4564-9135-49ea6afded97", "type": "concept", "title": "Equilibrium existence in examples"}, {"id": "d6f24b81-29a4-4610-8912-132eb0398e60", "type": "concept", "title": "Multiple equilibria and selection problems"}], "description": "Students learn to locate mutually stable choices and interpret what stability does and does not claim."}, {"id": "4c67a4af-d346-40da-86fc-e6f1702fd578", "type": "subtopic", "title": "Mixed strategies", "children": [{"id": "77f75bf6-94fe-4742-84be-8b21c3b8bf99", "type": "concept", "title": "Indifference principle"}, {"id": "aae5faf2-7490-44f7-9788-617857b8ca53", "type": "concept", "title": "Support of a mixed strategy"}, {"id": "25695f7c-e52d-4623-b989-eea29776ed47", "type": "concept", "title": "Mixed equilibrium in zero-sum and nonzero-sum games"}], "description": "Randomization matters when predictable play can be exploited."}, {"id": "7aa9d697-2f6a-46a1-a113-6885cd54684a", "type": "subtopic", "title": "Existence and computation", "children": [{"id": "6b896284-2ea1-4c6a-9955-12ff68ae7e07", "type": "concept", "title": "Nash existence theorem intuition"}, {"id": "76559841-40b1-43c3-9cbc-70f3c4b34250", "type": "concept", "title": "Fixed-point ideas"}, {"id": "4f4b83be-37fd-4220-acc4-0bc185f3567e", "type": "concept", "title": "Numerical solving and verification"}], "description": "A world-class course gives students the formal and computational backbone behind equilibrium."}]}, {"id": "5fb70fa0-2ca9-4c5d-aec2-7be309b46b81", "type": "topic", "title": "Extensive-Form Games and Backward Induction", "description": "Model timing, observation, and sequential decisions using game trees and information sets.", "children": [{"id": "514fdc12-8331-4f34-8e58-7be5c9f8de67", "type": "subtopic", "title": "Game trees", "children": [{"id": "95d81cd4-9993-487d-82f7-5f5e2852d50c", "type": "concept", "title": "Nodes, branches, and terminal histories"}, {"id": "6bc762fe-a5d9-4f8a-91fc-d8f047c9212d", "type": "concept", "title": "Strategies versus actions"}, {"id": "fe2007a9-404c-4232-a1f4-595e41faae3d", "type": "concept", "title": "Payoffs at terminal nodes"}], "description": "Extensive-form games expose the order of moves and possible histories."}, {"id": "0c1dc04b-de73-45d0-8493-2d9b38111a02", "type": "subtopic", "title": "Information sets", "children": [{"id": "b71c4096-dba2-4ac2-8256-d136a754f90a", "type": "concept", "title": "Perfect information"}, {"id": "a7522afe-74b6-4a08-a25f-a3b735f9cac3", "type": "concept", "title": "Imperfect information"}, {"id": "497866b9-d9bf-4bdc-86bb-07c064c2915a", "type": "concept", "title": "Behavioral strategies"}], "description": "Information sets model what a player can and cannot distinguish during play."}, {"id": "63d9dbaf-d4b9-4ca0-ad96-0e3aaecdce3a", "type": "subtopic", "title": "Backward induction", "children": [{"id": "db7aea32-01cd-41e4-a3ef-1e81c8ce8a40", "type": "concept", "title": "Finite perfect-information games"}, {"id": "8379974b-133c-4d5c-9b64-c7fbfd3dc45c", "type": "concept", "title": "Rollback reasoning"}, {"id": "2e3ac68c-e8c3-43ba-9075-f3fda9b96bf9", "type": "concept", "title": "Backward induction paradoxes and limits"}], "description": "Students learn to reason from future consequences back to present choices."}]}, {"id": "697c7a6e-5f50-4388-bd89-0461c2b797c7", "type": "topic", "title": "Subgame Perfection and Dynamic Commitment", "description": "Refine dynamic-game predictions by eliminating noncredible threats and promises.", "children": [{"id": "ebef119b-96ea-4799-bbd7-66ada56f81c0", "type": "subtopic", "title": "Subgames", "children": [{"id": "79e173c3-bada-4b98-8857-11f7e43dd657", "type": "concept", "title": "Proper subgames"}, {"id": "80bf60dd-fa6e-446c-98d4-93dff3e44235", "type": "concept", "title": "Continuation games"}, {"id": "65b9d14f-a775-431b-b0c0-611f2271a2ca", "type": "concept", "title": "Subgame-perfect equilibrium"}], "description": "Subgames isolate decision problems that should be credible on their own."}, {"id": "c04f539d-fa72-467e-867e-38cb85e07921", "type": "subtopic", "title": "Credibility", "children": [{"id": "15ebcd3f-35c0-4e14-82db-f7b11ef1bdd4", "type": "concept", "title": "Noncredible threats"}, {"id": "b604534a-3df9-4f72-a97b-544021cc4207", "type": "concept", "title": "Commitment devices"}, {"id": "4388d86e-e273-42e9-b2ec-f9bcfbd0564f", "type": "concept", "title": "Strategic delegation"}], "description": "Dynamic analysis distinguishes real threats from empty ones."}, {"id": "ebe2837f-ab89-4e17-a475-ed03bca9005b", "type": "subtopic", "title": "Dynamic applications", "children": [{"id": "ed909a61-a68f-4e63-93dc-0eb61c1f690f", "type": "concept", "title": "Entry games"}, {"id": "3e70230c-cb79-4fd5-9b11-93b598a07f1a", "type": "concept", "title": "Hold-up problems"}, {"id": "ce6745f7-c321-4441-a382-5d9a7ff0e8ea", "type": "concept", "title": "War of attrition and preemption"}], "description": "Students connect the refinement to entry deterrence, bargaining, and policy timing."}]}, {"id": "5c16d3c5-f318-4fd7-b4b9-64e86aa35721", "type": "topic", "title": "Repeated Games, Cooperation, and Reputation", "description": "Study how long-run relationships can support cooperation, punishment, trust, and strategic reputation.", "children": [{"id": "72748e3f-3b62-4e88-abac-b57497404e94", "type": "subtopic", "title": "Repeated interaction", "children": [{"id": "8f5ca5fb-fae6-42bd-92ff-b9536a4e03c1", "type": "concept", "title": "Finite versus infinite repetition"}, {"id": "8cc45cde-b6b0-41f2-ad87-abfadbb72b0e", "type": "concept", "title": "Discount factors"}, {"id": "5d63984d-3960-4c8a-a270-bb15f5c4d584", "type": "concept", "title": "Stage-game payoffs"}], "description": "Repeated games show how the future changes present incentives."}, {"id": "f930741c-5084-4126-9136-653346b25a0f", "type": "subtopic", "title": "Punishment and cooperation", "children": [{"id": "98bbeecf-2667-4864-9c21-3245519c94bf", "type": "concept", "title": "Trigger strategies"}, {"id": "9acc0285-42d7-4f93-b1a7-67a7fcb80244", "type": "concept", "title": "Grim punishment"}, {"id": "b50684dc-354a-4868-8324-1782e6d797db", "type": "concept", "title": "Tit-for-tat and forgiving strategies"}], "description": "Students learn how cooperation can be sustained without external enforcement."}, {"id": "69ab68e8-8861-4c77-b4bf-ad25687e04f2", "type": "subtopic", "title": "Reputation and folk theorems", "children": [{"id": "5a401620-465f-403c-be4b-13843832b948", "type": "concept", "title": "Folk theorem intuition"}, {"id": "eb3ba10f-025d-400b-8701-a3ef8dad2d60", "type": "concept", "title": "Reputation building"}, {"id": "70467a05-19f0-4441-b14b-2a94cf4f48ff", "type": "concept", "title": "Public and private monitoring"}], "description": "Long-run incentives can support many outcomes, making equilibrium selection central."}]}, {"id": "b5a61ba9-b69c-4fd7-b8a6-6f7276d0b8c7", "type": "topic", "title": "Bayesian Games and Incomplete Information", "description": "Analyze strategic decisions when players have private information and beliefs about types.", "children": [{"id": "2d90f312-048f-4932-8e92-ac9f3a49f28b", "type": "subtopic", "title": "Types and beliefs", "children": [{"id": "345b2406-1dac-4886-9b85-620efaa04319", "type": "concept", "title": "Type spaces"}, {"id": "b77dce1e-abda-459a-9e9a-1fdad3ea2a1e", "type": "concept", "title": "Common priors"}, {"id": "130d3810-64b0-4d53-9384-7c8f51144c64", "type": "concept", "title": "Expected payoffs by type"}], "description": "Private information is modeled through types, priors, and belief updating."}, {"id": "0ac9f823-3a99-4c0f-8ebe-fb2b7f70f0c8", "type": "subtopic", "title": "Bayesian Nash equilibrium", "children": [{"id": "de887b93-55fa-4f3e-ad86-42c2dbfdadaa", "type": "concept", "title": "Type-contingent strategies"}, {"id": "ae70dd80-1631-4631-94b0-623524cfde74", "type": "concept", "title": "Equilibrium consistency"}, {"id": "47750c5e-5c4c-4464-8fec-6f4f58e32e80", "type": "concept", "title": "Adverse selection examples"}], "description": "Players choose strategies that are optimal given beliefs about others' types."}, {"id": "9a429ef5-7917-46d5-baec-fdd65895e372", "type": "subtopic", "title": "Information value", "children": [{"id": "fb76c73a-8908-4aff-a646-2d22c4a9015e", "type": "concept", "title": "Value of information"}, {"id": "7b306d95-e5e0-42cd-86b7-031cc8ca35e9", "type": "concept", "title": "Winner's curse preview"}, {"id": "b22cf799-4550-4d13-9484-cfd9ff6fe230", "type": "concept", "title": "Information aggregation"}], "description": "Students evaluate how uncertainty changes incentives and welfare."}]}, {"id": "0fa68036-eb5d-4765-b4d8-ebcac3d4091d", "type": "topic", "title": "Signaling, Screening, and Information Economics", "description": "Understand how informed and uninformed parties communicate, sort, and reveal hidden information.", "children": [{"id": "425dc483-bf6c-443d-884b-164efb6285f1", "type": "subtopic", "title": "Signaling games", "children": [{"id": "566fd92d-0d9b-4713-afc2-1f24e754cc5b", "type": "concept", "title": "Sender and receiver strategies"}, {"id": "bc3a224e-e9ec-4060-a15d-d5539443fb58", "type": "concept", "title": "Pooling and separating equilibria"}, {"id": "62191823-948c-45cf-9a97-a683e6c20fdf", "type": "concept", "title": "Education and product-quality signaling"}], "description": "Informed players may take costly actions to communicate private information."}, {"id": "325c7c0d-4474-4e48-9aac-004218dfe7cc", "type": "subtopic", "title": "Screening", "children": [{"id": "557426d7-e7a6-4629-afc6-7224e2eb9ae5", "type": "concept", "title": "Incentive compatibility"}, {"id": "80922b17-eee7-4294-bc8f-afb9a9690659", "type": "concept", "title": "Participation constraints"}, {"id": "023f4f9d-a119-4f0e-9f9f-118540c16c29", "type": "concept", "title": "Insurance and nonlinear pricing"}], "description": "Uninformed players design menus that induce self-selection."}, {"id": "0676a86f-aa7c-4f39-8e1c-2296067c80b3", "type": "subtopic", "title": "Equilibrium refinements", "children": [{"id": "b434316a-56db-4022-b70b-f3ed575a50bd", "type": "concept", "title": "Perfect Bayesian equilibrium"}, {"id": "1864321e-931c-4b5f-a353-45852faa2790", "type": "concept", "title": "Sequential equilibrium intuition"}, {"id": "cae39b44-5764-4c2d-a97e-51daa8f0e0d9", "type": "concept", "title": "Intuitive criterion preview"}], "description": "Information games often need refinements to rule out implausible beliefs."}]}, {"id": "ba05c9fb-7b1d-4775-8ce3-0988c42b2a94", "type": "topic", "title": "Principal-Agent Problems and Contract Design", "description": "Model incentive conflicts when one party delegates action to another under imperfect observability.", "children": [{"id": "cc750b69-9aa7-41ff-8f0f-79084f42fcd2", "type": "subtopic", "title": "Moral hazard", "children": [{"id": "4637acbb-46c4-43e5-8bab-684379c9f730", "type": "concept", "title": "Hidden action"}, {"id": "5679b319-6e31-441b-b020-e7777be7509d", "type": "concept", "title": "Risk sharing"}, {"id": "c183dd34-b929-4916-865e-268316d60d30", "type": "concept", "title": "Performance pay and incentive intensity"}], "description": "The core issue is how to motivate effort when actions are hidden or costly to monitor."}, {"id": "d6510231-8dba-4410-83b1-29b53aede58d", "type": "subtopic", "title": "Adverse selection", "children": [{"id": "d73e4747-3673-4de8-9289-63564b70a6e2", "type": "concept", "title": "Hidden information"}, {"id": "e28c14b2-ce23-4160-919b-4726b6abbdc8", "type": "concept", "title": "Self-selection menus"}, {"id": "8d845d75-d120-4cf8-8c01-9e82348d6026", "type": "concept", "title": "Information rents"}], "description": "Contracts must handle hidden type or quality before agreement."}, {"id": "5518f857-b7ee-4a62-a5b3-4d70b73d8720", "type": "subtopic", "title": "Contract limits", "children": [{"id": "519f28ca-dfb0-4402-9126-561fc1164ccd", "type": "concept", "title": "Limited liability"}, {"id": "33288ed7-a2c7-44e9-bd68-8f98b75410bb", "type": "concept", "title": "Multitasking distortions"}, {"id": "98743255-d9bc-4083-9148-839b76bed7d1", "type": "concept", "title": "Relational contracts"}], "description": "Students learn why optimal contracts balance incentives, risk, measurement, and enforceability."}]}, {"id": "5254c3b2-dd4a-4a4f-8fbd-9ab4e8301936", "type": "topic", "title": "Bargaining, Negotiation, and Cooperative Games", "description": "Compare strategic and cooperative models of surplus division, coalition formation, and negotiation power.", "children": [{"id": "a5fe57f3-2a3d-4e48-9f84-4b16b39c1b7b", "type": "subtopic", "title": "Bargaining models", "children": [{"id": "6c593477-8376-4cec-9359-115a9d410668", "type": "concept", "title": "Nash bargaining solution"}, {"id": "3f0fbca4-7169-4818-9d03-f156777e3707", "type": "concept", "title": "Alternating-offers model"}, {"id": "1efe65d0-672c-4acc-844b-8a94f1d77c5f", "type": "concept", "title": "Outside options and disagreement payoffs"}], "description": "Bargaining theory studies how surplus is divided under patience, outside options, and commitment."}, {"id": "2ef6ffd8-5e39-427c-99c9-951146e4604e", "type": "subtopic", "title": "Coalitions", "children": [{"id": "1042827b-a52a-45c0-83fb-dae820d52e07", "type": "concept", "title": "Characteristic functions"}, {"id": "d3f27911-af6b-4b86-bd50-bcddf98be603", "type": "concept", "title": "Core"}, {"id": "bb851522-940e-48b3-ba7f-e37a2673cc08", "type": "concept", "title": "Shapley value"}], "description": "Cooperative game theory asks what groups can achieve together and how gains should be allocated."}, {"id": "638ab6bb-7416-4bf1-8122-918b867f8c88", "type": "subtopic", "title": "Negotiation applications", "children": [{"id": "2b990e7e-6700-47a1-8ae2-d1bb121a4ecd", "type": "concept", "title": "Credible commitments"}, {"id": "276e2ed7-b6f3-40c7-83ce-160138abdb34", "type": "concept", "title": "Mediation and arbitration"}, {"id": "06ffad7a-b166-49eb-9e98-6975a9232554", "type": "concept", "title": "Incomplete contracts"}], "description": "Students connect formal models to real negotiation, conflict, and institutional design."}]}, {"id": "fc3f57e6-541e-4a26-ab61-a75c4eaa7075", "type": "topic", "title": "Auctions and Mechanism Design", "description": "Design rules that induce strategic agents to reveal information or allocate resources efficiently.", "children": [{"id": "93c7a08b-fb61-4c97-8e37-374b56e0c073", "type": "subtopic", "title": "Auction formats", "children": [{"id": "1c14eb60-5119-411d-bed9-862f30c28009", "type": "concept", "title": "English, Dutch, first-price, and second-price auctions"}, {"id": "bc8b51cf-4eea-4e25-8993-29c7740b371c", "type": "concept", "title": "Private values and common values"}, {"id": "a28856f7-5319-47f0-a547-8dc2f229b763", "type": "concept", "title": "Revenue equivalence intuition"}], "description": "Auction theory compares rules for allocating goods under strategic bidding."}, {"id": "90de7937-7d8c-48d1-879d-2cf0a5f00153", "type": "subtopic", "title": "Mechanism design foundations", "children": [{"id": "088ad697-6bd2-41dc-be2b-fe8c44df3078", "type": "concept", "title": "Direct mechanisms"}, {"id": "649699ba-e7d8-43a8-953e-b6b2fe5c1b1e", "type": "concept", "title": "Revelation principle"}, {"id": "ffeebba8-09d5-4c8f-8443-fe3c000e1d79", "type": "concept", "title": "Incentive compatibility"}], "description": "Mechanism design reverses game theory: choose the game to produce desired outcomes."}, {"id": "43ccfe8f-5cad-4319-a891-9ead2b80d4cb", "type": "subtopic", "title": "Market-design applications", "children": [{"id": "175730c0-6fd3-4cd8-b84f-3115b3a58162", "type": "concept", "title": "Spectrum auctions"}, {"id": "c791e331-feb6-4dd3-8c5f-91b3b7901ccb", "type": "concept", "title": "Procurement and scoring auctions"}, {"id": "2e09e267-2426-479b-8279-ac0f1b3aefa3", "type": "concept", "title": "School choice and kidney exchange preview"}], "description": "Students see how mechanisms shape real allocation systems."}]}, {"id": "30a7642d-1f2a-4f11-b137-ed11c3ed6542", "type": "topic", "title": "Oligopoly, Pricing, Platforms, and Market Design Applications", "description": "Apply game theory to firms, markets, regulation, matching, and digital platforms.", "children": [{"id": "63624782-23d6-4365-aee2-457043d343cc", "type": "subtopic", "title": "Oligopoly models", "children": [{"id": "476efa6d-d172-4470-9a3c-8cced43ccf3a", "type": "concept", "title": "Cournot quantity competition"}, {"id": "bafb2d76-f67c-4285-960e-b08cb5d1c307", "type": "concept", "title": "Bertrand price competition"}, {"id": "e0f2cdae-8fab-4d54-95c2-929f1f94c816", "type": "concept", "title": "Stackelberg leadership"}], "description": "Firms' choices are interdependent, so strategic models explain price, output, and entry."}, {"id": "bf5688f9-5776-44ed-bf74-a557283434d7", "type": "subtopic", "title": "Pricing and platforms", "children": [{"id": "67570da0-a8c1-4b35-b3fc-01561e9a3f74", "type": "concept", "title": "Price discrimination"}, {"id": "baf58f99-42a0-4097-b9e6-b10bca975a15", "type": "concept", "title": "Two-sided markets"}, {"id": "d418286b-fbdf-4501-837e-18d497d81e4a", "type": "concept", "title": "Network effects"}], "description": "Digital and networked markets make strategic pricing and participation especially important."}, {"id": "a8a6c39f-2f48-47fd-92a8-2d3e266c38af", "type": "subtopic", "title": "Policy and regulation", "children": [{"id": "cae0150d-c2fb-4e45-babc-9e74f8a74ae2", "type": "concept", "title": "Antitrust and collusion"}, {"id": "bd569a1d-5176-431f-a7fa-5eef6175ed00", "type": "concept", "title": "Entry deterrence"}, {"id": "5ffed404-c6da-420f-ac70-c518be434b38", "type": "concept", "title": "Regulatory mechanism design"}], "description": "Game theory helps evaluate market power, collusion, and institutional rules."}]}, {"id": "bc505ca6-5e0b-46c9-9509-17c7ed55b687", "type": "topic", "title": "Evolutionary, Learning, Behavioral, and Experimental Games", "description": "Study how strategies emerge through adaptation, bounded rationality, experiments, and social preferences.", "children": [{"id": "18ca5bbb-fbbf-4057-8739-557ee065b3b6", "type": "subtopic", "title": "Evolutionary games", "children": [{"id": "0cdd4be6-2aaa-4bee-bccf-8f325307bfce", "type": "concept", "title": "Evolutionarily stable strategies"}, {"id": "7042f517-7fbc-4da2-9b2d-698ee42c2608", "type": "concept", "title": "Replicator dynamics"}, {"id": "027d5882-a6fb-42cd-9230-5d51ecab6c37", "type": "concept", "title": "Hawk-dove and coordination examples"}], "description": "Evolutionary models study strategy survival through adaptation rather than full rational calculation."}, {"id": "d2ea9d59-9f3b-40b1-acc4-4d6bdd8dd97b", "type": "subtopic", "title": "Learning in games", "children": [{"id": "07484054-f79e-4bf6-aba5-bf4dd3adf356", "type": "concept", "title": "Fictitious play"}, {"id": "10061d12-6568-4fee-8cb9-b815cccd3169", "type": "concept", "title": "Reinforcement learning intuition"}, {"id": "34f64fc9-71af-45ae-af68-fb4d2faff3f7", "type": "concept", "title": "Best-response dynamics"}], "description": "Players may learn through experience, feedback, and adjustment."}, {"id": "5ef32c7f-ee79-4d35-a365-e8de44f9cec0", "type": "subtopic", "title": "Behavioral and experimental evidence", "children": [{"id": "403f6c5e-55a0-4825-bfab-70879bc77745", "type": "concept", "title": "Ultimatum and dictator games"}, {"id": "162b4e1b-5c58-4405-b16e-a79be2f7cffd", "type": "concept", "title": "Public-goods experiments"}, {"id": "891151b4-30ba-49b5-9c79-a8adeb4d33d3", "type": "concept", "title": "Level-k and cognitive hierarchy models"}], "description": "Experiments reveal fairness, reciprocity, bounded rationality, and systematic deviations from narrow payoff maximization."}]}, {"id": "035c084f-64ae-477e-9619-dcc7c4587e89", "type": "topic", "title": "Network, Matching, and Computational Game Theory", "description": "Extend strategic analysis to networks, matching markets, algorithms, and computational complexity.", "children": [{"id": "0be01a9a-e4a9-436f-8255-1cf9cbe686b3", "type": "subtopic", "title": "Network games", "children": [{"id": "8dc054ca-85c3-41ee-b983-252b0e6afd53", "type": "concept", "title": "Strategic complements and substitutes"}, {"id": "6bb11eb6-a3d9-4ee7-8c63-5d340997e56a", "type": "concept", "title": "Diffusion and cascades"}, {"id": "3306499a-b82b-45f9-876c-bb4e8b1c3ff5", "type": "concept", "title": "Peer effects"}], "description": "Networks shape who interacts with whom and how local incentives produce aggregate outcomes."}, {"id": "eeff20c6-7d2f-4bd9-936a-db9855345ee8", "type": "subtopic", "title": "Matching markets", "children": [{"id": "efe81eff-a11d-4d03-8860-8d2e5d83a696", "type": "concept", "title": "Stable matching"}, {"id": "e7ec3a16-42c1-4ee5-80fa-802397a129bd", "type": "concept", "title": "Deferred acceptance"}, {"id": "cfe12704-d4fb-48d5-8e8d-c480f5bf02c5", "type": "concept", "title": "School choice and labor matching"}], "description": "Matching theory studies allocation without prices or with constrained prices."}, {"id": "7d45bff8-f163-49cf-8d92-83e4a2ec6f5e", "type": "subtopic", "title": "Computational game theory", "children": [{"id": "caa4df67-2471-4b88-ad96-a22b0874c002", "type": "concept", "title": "Complexity of equilibrium computation"}, {"id": "51289daf-3c57-47b2-86ef-73d4bb194d4b", "type": "concept", "t